return $input.all().map((item, i) => {
  const j = item.json;
  const fail = m => { throw new Error('SETUP: ' + m); };
  const raw = String(j.sheet_url || '').trim();
  const sheetId = raw.match(/\/spreadsheets\/d\/([\w-]+)/)?.[1] || (/^[\w-]{20,}$/.test(raw) ? raw : '');
  if (!sheetId) fail('Open Workshop Setup and paste your Google Sheet URL into sheet_url.');
  const tab = String(j.sheet_tab || '').trim();
  if (!tab) fail('Enter the exact bottom tab name in sheet_tab, for example Sheet1.');
  function channel(value, field) {
    const s = String(value || '').trim();
    const id = s.match(/(?:\/archives\/|\/client\/[^/]+\/)([CG][A-Z0-9]+)/)?.[1] || s;
    if (!/^[CG][A-Z0-9]{8,}$/.test(id)) fail('Paste the Channel ID or channel link into ' + field + '. A #channel-name is not an ID.');
    return id;
  }
  const product = channel(j.product_channel_id, 'product_channel_id');
  const support = channel(j.support_channel_id, 'support_channel_id');
  if (product === support) fail('Use two different channels for product feedback and support.');
  const isSetupCheck = !j.id;
  const sender = j.from?.value?.[0]?.address || '';
  const body = String(j.text || '').slice(0, 4000);
  if (!isSetupCheck && (!sender || !body.trim())) fail('Gmail must have Simplify OFF and the test email must include plain text.');
  const quotedTab = "'" + tab.replace(/'/g, "''") + "'";
  return {json:{sender,sender_display:j.from?.text || sender,received_at:j.date || '',subject:j.subject || '',body,message_id:j.id || '',isSetupCheck,
    sheetId,sheet_tab:tab,headerRange:encodeURIComponent(quotedTab+'!A1:D1'),appendRange:encodeURIComponent(quotedTab+'!A:D'),product_channel_id:product,support_channel_id:support},pairedItem:{item:i}};
});

