return $input.all().map((item,i) => {
  const j = item.json;
  if (j.error) throw new Error('SETUP: Google Sheets could not be read. Select your Google Sheets credential, check edit access and the sheet_url / sheet_tab. ' + String(j.error.message || ''));
  const expected = ['time','sender','category','draft_reply'];
  const actual = expected.map(k => j[k]);
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error('SETUP: Row 1, cells A1:D1 must be exactly time, sender, category, draft_reply, in that order. Import the supplied CSV into the tab named in Workshop Setup.');
  return {json:$('2. Capture Sender, Time & Body').all()[i].json,pairedItem:{item:i}};
});

return $input.all().map((item,i) => {
  const product = $('Check product channel').all()[i].json;
  const support = item.json;
  for (const [role, result] of [['product',product],['support',support]]) {
    if (!result.id || result.error) throw new Error('SETUP: Slack cannot access the ' + role + ' channel (' + String(result.error || 'invalid response') + '). Use the channel ID from the SAME workspace as your Slack credential. Add the connected Slack app/user to that channel; reconnect the correct workspace if needed.');
    if (result.is_archived) throw new Error('SETUP: The ' + role + ' channel is archived. Choose an active channel.');
    if (result.is_member === false) throw new Error('SETUP: Add the connected Slack app/user to the ' + role + ' channel, then run Check setup again.');
  }
  return {json:{...$('2. Capture Sender, Time & Body').all()[i].json,setup_status:'READY - Sheet headers and both Slack channels verified. For an end-to-end test, send a NEW [KAAPI-DEMO] email while the Gmail trigger is listening.'},pairedItem:{item:i}};
});

return $input.all().map((item,i) => {
  const j = item.json;
  const source = $('4. Keep Sender, Time & Result').all()[i].json;
  if (j.error || ['time','sender','category','draft_reply'].some(k => j[k] !== source[k])) throw new Error('SHEET WRITE FAILED: Expected one row with four matching fields. Check Sheet edit access. No Slack message was posted.');
  return {json:source,pairedItem:{item:i}};
});
